import { z as z43 } from "zod";
var hash8 = z43.string().regex(/^[a-f0-9]{64}$/);
var identity2 = z43.object({ id: z43.string().min(1), hash: hash8 }).strict();
var catalogCoverageSchema = z43.object({
  version: z43.literal(1),
  capturedAt: z43.string(),
  consistency: z43.enum(["stable_double_read", "changed_during_read"]),
  scopeHash: hash8,
  inventoryHash: hash8,
  entries: z43.array(identity2.extend({
    label: z43.string(),
    family: z43.string(),
    status: z43.string(),
    authorshipRevision: z43.number().int().nonnegative(),
    sourceKey: z43.string(),
    isVariant: z43.boolean(),
    indexState: z43.enum(["present", "missing", "mismatch"]),
    disposition: z43.enum(["eligible_card", "excluded", "blocked"]),
    reasons: z43.array(z43.string().min(1))
  }).strict()),
  indexed: z43.array(identity2.extend({ cardHash: hash8 }).strict()),
  issues: z43.array(z43.object({ code: z43.string().min(1), id: z43.string().nullable() }).strict()),
  receiptHash: hash8
}).strict();
var electionCandidatesSchema = z43.object({
  version: z43.literal(1),
  catalogReceiptHash: hash8,
  offers: z43.array(z43.object({
    offerId: z43.string().min(1),
    signature: hash8,
    family: z43.string(),
    sourceId: z43.string(),
    slides: z43.array(identity2.extend({ role: z43.string(), slideIndex: z43.number().int().nonnegative() }).strict())
  }).strict()),
  cards: z43.array(identity2.extend({ offerIds: z43.array(z43.string()), reasons: z43.array(z43.string()) }).strict()),
  selectionProfiles: z43.array(z43.object({ offerId: z43.string(), hash: hash8, profile: compactOfferProfileSchema }).strict()).optional(),
  receiptHash: hash8
}).strict();
var electionClassificationSchema = z43.object({
  version: z43.literal(1),
  candidatesReceiptHash: hash8,
  method: z43.enum(["all_sent_to_selector", "scored_batches"]),
  evaluated: z43.array(identity2.extend({ score: z43.number().min(0).max(4), confidence: z43.number().min(0).max(1) }).strict()),
  shortlistIds: z43.array(z43.string()),
  selectorIds: z43.array(z43.string()),
  operationKeys: z43.array(z43.string()),
  batches: z43.number().int().nonnegative(),
  ranking: z43.array(z43.object({
    id: z43.string(),
    score: z43.number().min(0).max(4),
    recencyPenalty: z43.number().min(0).max(0.3),
    similarityPenalty: z43.number().min(0).max(0.75),
    adjustedScore: z43.number(),
    shortlistPosition: z43.number().int().min(1).max(12).nullable()
  }).strict()).optional(),
  issues: z43.array(z43.string()),
  receiptHash: hash8
}).strict();
var electionDecisionSchema = z43.object({
  version: z43.literal(1),
  classificationReceiptHash: hash8,
  choices: z43.array(z43.object({
    slot: z43.number().int().min(0).max(2),
    originalOfferId: z43.string(),
    chosenOfferId: z43.string(),
    reason: z43.string(),
    substitutionReason: z43.string().nullable()
  }).strict()).length(3),
  receiptHash: hash8
}).strict();
var electionDecisionV2Schema = electionDecisionSchema.extend({ version: z43.literal(2), choices: z43.array(electionDecisionSchema.shape.choices.element.extend({ editorialApproach: z43.string().min(1).max(600).nullable() })).length(3) });

