import { z as z44 } from "zod";
var arsenalOfferSchema = z44.object({
  candidate: pinnedCandidateV2Schema,
  name: z44.string().min(1).max(160),
  description: z44.string().max(800),
  pieces: z44.record(z44.string().regex(/^[a-f0-9]{64}$/), arsenalPieceSchema),
  assets: z44.array(arsenalAssetSchema).max(20)
}).strict();
var arsenalCopySchema = z44.object({
  content: designContentGenerationSchema,
  designCandidateId: z44.string().min(1),
  tone: z44.string().min(1),
  imagePrompt: z44.string(),
  backgroundColor: z44.string().regex(/^#[a-fA-F0-9]{6}$/),
  textColor: z44.string().regex(/^#[a-fA-F0-9]{6}$/),
  accentColor: z44.string().regex(/^#[a-fA-F0-9]{6}$/),
  layout: z44.enum(["centered", "left-aligned", "split", "minimal"]),
  aspectRatio: z44.enum(["1:1", "4:5", "5:6", "9:16"]),
  copyAngle: z44.object({
    type: z44.enum([
      "dor",
      "beneficio",
      "objecao",
      "autoridade",
      "escassez",
      "storytelling",
      "mito_vs_verdade"
    ]),
    label: z44.string().min(1)
  }).strict()
}).strict();
var arsenalCompilationReportSchema = z44.object({
  traceId: z44.string().uuid(),
  runId: z44.string().uuid(),
  slot: z44.number().int().min(0).max(2),
  materializationId: z44.string().uuid(),
  userContentHash: z44.string().regex(/^[a-f0-9]{64}$/),
  selectedCandidateId: z44.string().max(240).nullable(),
  status: z44.enum(["applied", "adapted", "fallback", "needs_adjustment"]),
  durationMs: z44.number().min(0).max(3e5),
  attempts: z44.array(
    z44.object({
      candidateId: z44.string().max(240),
      policy: z44.enum(["normal", "adapt"]),
      reasons: z44.array(z44.string().max(160)).max(16),
      durationMs: z44.number().min(0).max(3e5)
    }).strict()
  ).max(6)
}).strict();

