var DESCRIPTOR_VERSION = "structural-v1";
var clamp = (n2) => Math.max(0, Math.min(1, n2));
var round = (n2) => Number(n2.toFixed(6));
var mean = (xs) => xs.reduce((s, n2) => s + n2, 0) / Math.max(1, xs.length);
